1669	  <script>
1670	    function updateCountdown(){
1671	      const target = new Date("2026-04-11T09:00:00").getTime();
1672	      const now = new Date().getTime();
1673	      const diff = target - now;
1674	      const el = document.getElementById("countdown");
1675	      if(!el) return;
1676	      if(diff <= 0){
1677	        el.textContent = "活動已開始";
1678	        return;
1679	      }
1680	      const d = Math.floor(diff / (1000 * 60 * 60 * 24));
1681	      const h = Math.floor((diff / (1000 * 60 * 60)) % 24);
1682	      const m = Math.floor((diff / (1000 * 60)) % 60);
1683	      el.textContent = d + " 天 " + h + " 小時 " + m + " 分";
1684	    }
1685	
1686	    function updateRegistrationStats(){
1687	      const maxSeats = 200;
1688	      const baseRegistered = 20;
1689	      const startTime = new Date("2026-03-26T12:00:00").getTime();
1690	      const incrementInterval = 2 * 60 * 60 * 1000; // 每 2 小時 +1
1691	      const now = new Date().getTime();
1692	
1693	      let registered = baseRegistered;
1694	      if(now > startTime){
1695	        const increments = Math.floor((now - startTime) / incrementInterval);
1696	        registered = Math.min(maxSeats, baseRegistered + increments);
1697	      }
1698	
1699	      const remaining = Math.max(0, maxSeats - registered);
1700	
1701	      const maxSeatsEl = document.getElementById("maxSeats");
1702	      const registeredEl = document.getElementById("registeredCount");
1703	      const remainingEl = document.getElementById("remainingCount");
1704	
1705	      if(maxSeatsEl) maxSeatsEl.textContent = maxSeats;
1706	      if(registeredEl) registeredEl.textContent = registered;
1707	      if(remainingEl) remainingEl.textContent = remaining;
1708	    }
1709	
1710	    updateCountdown();
1711	    updateRegistrationStats();
1712	    setInterval(updateCountdown, 60000);
1713	    setInterval(updateRegistrationStats, 60000);
1714	  </script>

